public static class RepairDetailedFont {
 public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling)throw new Exception("Idle required");var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.isDirty||scene.name!="ShoeTower")throw new Exception("Clean ShoeTower required");const string original="Assets/ShooterSurvival/Resources/UI/GmarketHarbor SDF.asset";const string owned="Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedMall-20261003T092859667/DetailedMall font.asset";if(AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(owned)!=null)throw new Exception("Owned font already exists");if(!AssetDatabase.CopyAsset(original,owned))throw new Exception("Font copy failed");var font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(owned);font.atlasPopulationMode=AtlasPopulationMode.Static;var root=UnityEngine.Object.FindFirstObjectByType<Chapter45Director>().transform.Find("DetailedMall_20261003");int count=0;foreach(var text in root.GetComponentsInChildren<TMP_Text>(true)){text.font=font;text.fontSharedMaterial=font.material;count++;}EditorUtility.SetDirty(font);AssetDatabase.SaveAssetIfDirty(font);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);return new{count,font=owned,staticAtlas=true};}
